import{_ as t,c as s,o as i,a2 as o}from"./chunks/framework.DcjMSgeM.js";const g=JSON.parse(`{"title":"","description":"","frontmatter":{"layout":"home","hero":{"name":"Cours Web BA2","text":"Syllabus","tagline":"HELHa - Bachelor en informatique de gestion","actions":[{"theme":"brand","text":"Commencer","link":"/seances/"},{"theme":"alt","text":"GitHub","link":"https://github.com/fpluquet/web_client_serveur"}]},"features":[{"title":"Architecture Web Moderne","details":"Maîtrise des concepts client-serveur, clients légers vs lourds, et architectures SPA"},{"title":"Node.js et Express","details":"Développement backend avec JavaScript, serveurs web et middleware"},{"title":"APIs RESTful","details":"Conception et développement d'APIs robustes suivant les principes REST"},{"title":"Sécurité et Tests","details":"Sécurisation des applications web et stratégies de tests complètes"}]},"headers":[],"relativePath":"index.md","filePath":"index.md","lastUpdated":1789546107000}`),n={name:"index.md"};function r(l,e,a,c,u,d){return i(),s("div",null,[...e[0]||(e[0]=[o('<h2 id="objectifs-du-cours" tabindex="-1">Objectifs du cours <a class="header-anchor" href="#objectifs-du-cours" aria-label="Permalink to &quot;Objectifs du cours&quot;">​</a></h2><p>Ce cours complet de développement web backend vous permettra de maîtriser les technologies et concepts essentiels du développement web moderne. À la fin de ce cours, vous serez capable de :</p><ul><li><strong>Concevoir des architectures web</strong> adaptées aux besoins (client léger/lourd)</li><li><strong>Développer des applications Node.js/Express</strong> robustes et évolutives</li><li><strong>Créer des APIs RESTful</strong> respectant les standards de l&#39;industrie</li><li><strong>Gérer les données</strong> avec différents types de bases de données</li><li><strong>Sécuriser vos applications</strong> contre les vulnérabilités courantes</li><li><strong>Tester efficacement</strong> vos applications (tests unitaires, intégration, E2E)</li><li><strong>Développer des PWA</strong> pour une expérience utilisateur optimale</li></ul><h2 id="programme-detaille" tabindex="-1">Programme détaillé <a class="header-anchor" href="#programme-detaille" aria-label="Permalink to &quot;Programme détaillé&quot;">​</a></h2><h3 id="🏗️-fondements-de-l-architecture-web" tabindex="-1">🏗️ <strong>Fondements de l&#39;Architecture Web</strong> <a class="header-anchor" href="#🏗️-fondements-de-l-architecture-web" aria-label="Permalink to &quot;🏗️ **Fondements de l&#39;Architecture Web**&quot;">​</a></h3><p><strong>Séance 1 : Architecture Client-Serveur et HTTP</strong></p><ul><li>Concepts fondamentaux client-serveur</li><li>Protocole HTTP et ses méthodes</li><li>Communication réseau et modèles de données</li></ul><p><strong>Séance 2 : Client Léger vs Client Lourd</strong></p><ul><li>Comparaison des approches architecturales</li><li>Avantages et inconvénients de chaque modèle</li><li>Choix technologiques selon le contexte</li></ul><h3 id="🚀-technologies-backend" tabindex="-1">🚀 <strong>Technologies Backend</strong> <a class="header-anchor" href="#🚀-technologies-backend" aria-label="Permalink to &quot;🚀 **Technologies Backend**&quot;">​</a></h3><p><strong>Séance 3 : Node.js et l&#39;Écosystème npm</strong></p><ul><li>Environnement d&#39;exécution JavaScript côté serveur</li><li>Modèle asynchrone et événementiel</li><li>Gestion des packages avec npm</li></ul><p><strong>Séance 4 : Serveurs Web avec Express.js</strong></p><ul><li>Framework Express pour Node.js</li><li>Routing et middleware</li><li>Gestion des requêtes et réponses HTTP</li></ul><p><strong>Séance 5 : Architecture Client Lourd et SPA</strong></p><ul><li>Single Page Applications (SPA)</li><li>JavaScript vanilla pour applications client-lourd</li><li>Gestion de l&#39;état côté client</li></ul><h3 id="🔌-apis-et-donnees" tabindex="-1">🔌 <strong>APIs et Données</strong> <a class="header-anchor" href="#🔌-apis-et-donnees" aria-label="Permalink to &quot;🔌 **APIs et Données**&quot;">​</a></h3><p><strong>Séance 6 : APIs RESTful</strong></p><ul><li>Principes et contraintes REST</li><li>Conception d&#39;APIs robustes</li><li>Codes de statut HTTP et bonnes pratiques</li></ul><p><strong>Séance 7 : Gestion des Données et Bases de Données</strong></p><ul><li>Interaction avec les bases de données</li><li>Pattern MVC (Modèle-Vue-Contrôleur)</li><li>ORM/ODM et requêtes optimisées</li></ul><h3 id="🛡️-qualite-et-securite" tabindex="-1">🛡️ <strong>Qualité et Sécurité</strong> <a class="header-anchor" href="#🛡️-qualite-et-securite" aria-label="Permalink to &quot;🛡️ **Qualité et Sécurité**&quot;">​</a></h3><p><strong>Séance 8 : Tests et Qualité du Code</strong></p><ul><li>Stratégies de test (unitaires, intégration, E2E)</li><li>Pyramide des tests</li><li>Outils de test pour Node.js</li></ul><p><strong>Séance 9 : Sécurité des Applications Web</strong></p><ul><li>Vulnérabilités courantes (OWASP Top 10)</li><li>Authentification et autorisation</li><li>Sécurisation des APIs</li></ul><h3 id="🌐-technologies-avancees" tabindex="-1">🌐 <strong>Technologies Avancées</strong> <a class="header-anchor" href="#🌐-technologies-avancees" aria-label="Permalink to &quot;🌐 **Technologies Avancées**&quot;">​</a></h3><p><strong>Séance 10 : Progressive Web Apps (PWA)</strong></p><ul><li>Concepts et caractéristiques des PWA</li><li>Service Workers et cache</li><li>Expérience utilisateur native sur le web</li></ul><p><strong>Séance 11 : Conclusion et Perspectives</strong></p><ul><li>Synthèse des compétences acquises</li><li>Tendances et évolutions du développement web</li><li>Préparation aux projets professionnels</li></ul><h2 id="structure-pedagogique" tabindex="-1">Structure pédagogique <a class="header-anchor" href="#structure-pedagogique" aria-label="Permalink to &quot;Structure pédagogique&quot;">​</a></h2><p>Chaque séance suit une approche progressive structurée en trois parties :</p><ol><li><strong>🎓 Théorie</strong> : Concepts fondamentaux et principes théoriques</li><li><strong>💻 Application</strong> : Exemples pratiques en Node.js/Express (et PHP en complément)</li><li><strong>🔧 Exercices</strong> : Travaux pratiques avec solutions détaillées pour consolider les acquis</li></ol><h2 id="competences-transversales-developpees" tabindex="-1">Compétences transversales développées <a class="header-anchor" href="#competences-transversales-developpees" aria-label="Permalink to &quot;Compétences transversales développées&quot;">​</a></h2><ul><li><strong>Pensée architecturale</strong> : Capacité à concevoir des systèmes évolutifs</li><li><strong>Résolution de problèmes</strong> : Debugging et optimisation d&#39;applications</li><li><strong>Sécurité</strong> : Développement sécurisé par design</li><li><strong>Collaboration</strong> : Utilisation d&#39;outils de développement collaboratif</li><li><strong>Veille technologique</strong> : Adaptation aux évolutions rapides du web</li></ul>',36)])])}const h=t(n,[["render",r]]);export{g as __pageData,h as default};
